            // "EntityName|KeyValue" to just "KeyValue". Existing documents
            // use the old format, so we preserve it with an id factory.
            entity.HasPartitionKey(b => b.Id);
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve the EF 8 id format ("Blog|<key>") for backward compatibility.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Infrastructure.IdFormatConvention());
    }
}
